  'demo.tour.ui.clickHint': 'Click the highlighted part to go on.',
  'demo.tour.ui.missing': 'That part of the screen is not showing right now. Go on with Next — the product is all yours meanwhile.',
  'demo.tour.ui.endTitle': 'That was the real product',
  'demo.tour.ui.endBody': 'Everything you just saw runs in your browser, with invented data. Keep exploring on your own, or start a workspace for your team.',
  'demo.tour.ui.keep': 'Keep exploring',
