  // Demo hub: product and sales roles, four tours, the three-question picker
  'demo.tour.role.seller': "Inside sales",
  'demo.tour.role.product': "Product",
  'demo.tour.sprint.title': "Plan a sprint, watch it burn down",
  'demo.tour.sprint.blurb': "The product team’s backlog against its capacity, a running sprint whose chart shows the scope it took on, and the team’s weeks ahead.",
  'demo.tour.sprint.1.title': "The next sprint, from the backlog",
  'demo.tour.sprint.1.body': "Pick stories for the next sprint here; the target and the team’s usual pace sit beside them.",
  'demo.tour.sprint.2.title': "Capacity before commitment",
  'demo.tour.sprint.2.body': "The bar fills as stories go in, and says so when the sprint holds more points than the team usually finishes.",
  'demo.tour.sprint.3.title': "A burndown that tells the truth",
  'demo.tour.sprint.3.body': "Work added halfway through shows as a step up, so a late sprint is explained rather than guessed at.",
  'demo.tour.sprint.4.title': "The weeks ahead, person by person",
  'demo.tour.sprint.4.body': "Open tasks by the week they are due, how many are promises to customers, and their points: who has room before you plan more.",
  'demo.tour.handover.title': "From won deal to the customer team",
  'demo.tour.handover.blurb': "Sales closes the deal; the people who look after the customer pick it up on the same page, with nothing lost on the way.",
  'demo.tour.handover.1.title': "Deals by stage",
  'demo.tour.handover.1.body': "Each column is a stage. Drag a deal to Won when it closes.",
  'demo.tour.handover.2.title': "The deal carries its story",
  'demo.tour.handover.2.body': "Who was involved, what was promised and when it renews stay with the deal, for whoever takes it next.",
  'demo.tour.handover.3.title': "The customer team’s view",
  'demo.tour.handover.3.body': "The customer is here the moment the deal is won: owner, health and the next promise on one card.",
  'demo.tour.handover-loop.title': "From a won deal to “we built it for you”",
  'demo.tour.handover-loop.blurb': "The hand-over card when Sales wins, requests linked to Product work, and the message back when it ships.",
  'demo.tour.handover-loop.1.title': "Sales just won this one",
  'demo.tour.handover-loop.1.body': "Cedarmoor Health signed a two-year renewal on the Sales pipeline. Open the customer.",
  'demo.tour.handover-loop.2.title': "One card, nothing lost",
  'demo.tour.handover-loop.2.body': "The people and where they stand, what Sales promised, what they still wait for from Product, the dates and the latest of the sales thread. Nobody had to write it up.",
  'demo.tour.handover-loop.3.title': "Confirm, and it has an owner",
  'demo.tour.handover-loop.3.body': "Pick who takes it over in Customer Success (or Onboarding, if your company has it) and the playbook to start. Ctrl+Enter does it from anywhere on the card.",
  'demo.tour.handover-loop.4.title': "A customer who asked for something",
  'demo.tour.handover-loop.4.body': "Quillfield Retail asked Product for two things. Open it.",
  'demo.tour.handover-loop.5.title': "What they are waiting for",
  'demo.tour.handover-loop.5.body': "Promises and the product work they asked for: status, sprint end and department, visible to anyone who sees the customer, without opening Product’s board.",
  'demo.tour.handover-loop.6.title': "It shipped: tell them",
  'demo.tour.handover-loop.6.body': "When the work was finished, the owner got a task and this drafted message. Copy it into your email, or close their portal request. Nothing is sent by itself.",
  'demo.tour.handover-loop.7.title': "Link the next request",
  'demo.tour.handover-loop.7.body': "Search Product’s work and link the request in two keystrokes. Product’s backlog then shows how many customers wait, what they are worth and who renews soonest.",
  'demo.tour.move-in.title': "Bring your own file",
