  "demo.tour.onboarding-hub.title": "Your getting-started plan",
  "demo.tour.onboarding-hub.blurb": "One shared plan: the next thing to do, whose turn it is, steps that tick themselves, shared issues and the data checks.",
  "demo.tour.onboarding-hub.1.title": "The one thing to do next",
  "demo.tour.onboarding-hub.1.body": "Always at the top: the next open step, whose turn it is and for how long, and one button that takes you there.",
  "demo.tour.onboarding-hub.2.title": "Weighted progress",
  "demo.tour.onboarding-hub.2.body": "Required steps count fully, optional ones half. The dot marks what was expected by today, and the counters say who is waited on.",
  "demo.tour.onboarding-hub.3.title": "Steps that tick themselves",
  "demo.tour.onboarding-hub.3.body": "Inviting the team, an import, a connection that ran cleanly: Curahold sees them and ticks the step. A locked step says what it waits for.",
  "demo.tour.onboarding-hub.4.title": "Shared issues",
  "demo.tour.onboarding-hub.4.body": "Each says whose move it is. A failed setup test is one row here, with a button to test again; an issue can be a support ticket, never a copy of one.",
  "demo.tour.onboarding-hub.5.title": "Expected and received",
  "demo.tour.onboarding-hub.5.body": "Every mapped field is held to four rules: type, format, required and empty. A row that is fixed leaves the failing list at once.",
  "demo.tour.onboarding-hub.6.title": "A view for each role",
  "demo.tour.onboarding-hub.6.body": "The project lead sees everything, the sponsor the summary, the technical owner the steps, data and issues. Share the report as a read-only link or print it.",
  "demo.tour.onboarding-hub.7.title": "Your customers' plans",
  "demo.tour.onboarding-hub.7.body": "The same plan, for each customer you onboard: opened by a won deal, seen by the customer in your portal, with stall flags across all of them.",
